1	package com.example.starter.maintenance;
2	
3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
6	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
7	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
8	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
9	
10	import java.util.ArrayList;
11	import java.util.HashSet;
12	import java.util.List;
13	import java.util.Set;
14	import java.util.concurrent.CountDownLatch;
15	import java.util.concurrent.ExecutorService;
16	import java.util.concurrent.Executors;
17	import java.util.concurrent.Future;
18	import java.util.concurrent.TimeUnit;
19	
20	import org.junit.jupiter.api.AfterEach;
21	import org.junit.jupiter.api.BeforeEach;
22	import org.junit.jupiter.api.Test;
23	import org.springframework.beans.factory.annotation.Autowired;
24	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
25	import org.springframework.boot.test.context.SpringBootTest;
26	import org.springframework.http.MediaType;
27	import org.springframework.jdbc.core.JdbcTemplate;
28	import org.springframework.test.web.servlet.MockMvc;
29	import org.springframework.test.web.servlet.MvcResult;
30	
31	/**
32	 * 并发与幂等边界测试：真实 H2 数据库上的并发写协调，断言响应与最终数据一致性。
33	 */
34	@SpringBootTest
35	@AutoConfigureMockMvc
36	class EquipmentConcurrencyTests {
37	
38	    @Autowired
39	    private MockMvc mockMvc;
40	
41	    @Autowired
42	    private JdbcTemplate jdbc;
43	
44	    private ExecutorService executor;
45	
46	    @BeforeEach
47	    void setUp() {
48	        jdbc.update("DELETE FROM idempotency_request");
49	        jdbc.update("DELETE FROM maintenance");
50	        jdbc.update("DELETE FROM reading_revision");
51	        jdbc.update("DELETE FROM reading");
52	        jdbc.update("DELETE FROM equipment");
53	        executor = Executors.newFixedThreadPool(8);
54	    }
55	
56	    @AfterEach
57	    void tearDown() {
58	        executor.shutdownNow();
59	    }
60	
61	    private void register(String equipmentId, long periodMinutes) throws Exception {
62	        mockMvc.perform(post("/api/equipment")
63	                        .contentType(MediaType.APPLICATION_JSON)
64	                        .content("""
65	                                {"requestId":"reg-%s","equipmentId":"%s","maintenancePeriodMinutes":%d}
66	                                """.formatted(equipmentId, equipmentId, periodMinutes)))
67	                .andExpect(status().isCreated());
68	    }
69	
70	    private MvcResult postJson(String url, String body) throws Exception {
71	        return mockMvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(body))
72	                .andReturn();
73	    }
74	
75	    /** 并发同 requestId 同参数：全部得到原成功结果，业务效果只发生一次。 */
76	    @Test
77	    void concurrentSameRequestId_replaysSingleEffect() throws Exception {
78	        register("eq-cid", 1000);
79	        int threads = 8;
80	        CountDownLatch gate = new CountDownLatch(1);
81	        String body = """
82	                {"requestId":"cid-1","expectedVersion":1,"readingId":"r1",
83	                 "sampledAt":"2026-01-01T10:00:00Z","cumulativeMinutes":100}
84	                """;
85	        List<Future<MvcResult>> futures = new ArrayList<>();
86	        for (int i = 0; i < threads; i++) {
87	            futures.add(executor.submit(() -> {
88	                gate.await(5, TimeUnit.SECONDS);
89	                return postJson("/api/equipment/eq-cid/readings", body);
90	            }));
91	        }
92	        gate.countDown();
93	
94	        Set<String> bodies = new HashSet<>();
95	        for (Future<MvcResult> future : futures) {
96	            MvcResult result = future.get(15, TimeUnit.SECONDS);
97	            assertEquals(201, result.getResponse().getStatus(),
98	                    "并发同键同参应全部重放成功结果");
99	            bodies.add(result.getResponse().getContentAsString());
100	        }
101	        assertEquals(1, bodies.size(), "所有并发响应应完全相同（重放同一成功结果）");
102	
103	        // 业务效果只发生一次：一条读数、一条修订、版本仅加一
104	        mockMvc.perform(get("/api/equipment/eq-cid/readings"))
105	                .andExpect(status().isOk())
106	                .andExpect(jsonPath("$.length()").value(1));
107	        mockMvc.perform(get("/api/equipment/eq-cid/status"))
108	                .andExpect(jsonPath("$.version").value(2));
109	        Integer idemCount = jdbc.queryForObject(
110	                "SELECT COUNT(*) FROM idempotency_request WHERE request_id = 'cid-1'", Integer.class);
111	        assertEquals(1, idemCount, "同一 requestId 只应占一个幂等键");
112	    }
113	
114	    /** 并发修订与完成保养（同一期望版本）：恰有一个成功，已完成保养的锚点不发生变化。 */
115	    @Test
116	    void concurrentReviseVsMaintenance_anchorStable() throws Exception {
117	        register("eq-race", 1000);
118	        postJson("/api/equipment/eq-race/readings", """
119	                {"requestId":"race-r1","expectedVersion":1,"readingId":"r1",
120	                 "sampledAt":"2026-01-01T10:00:00Z","cumulativeMinutes":100}
121	                """);
122	        postJson("/api/equipment/eq-race/readings", """
123	                {"requestId":"race-r2","expectedVersion":2,"readingId":"r2",
124	                 "sampledAt":"2026-01-01T11:00:00Z","cumulativeMinutes":200}
125	                """);
126	
127	        CountDownLatch gate = new CountDownLatch(1);
128	        Future<MvcResult> reviseFuture = executor.submit(() -> {
129	            gate.await(5, TimeUnit.SECONDS);
130	            return postJson("/api/equipment/eq-race/readings/r1/revisions", """
131	                    {"requestId":"race-revise","expectedVersion":3,"cumulativeMinutes":150}
132	                    """);
133	        });
134	        Future<MvcResult> maintenanceFuture = executor.submit(() -> {
135	            gate.await(5, TimeUnit.SECONDS);
136	            return postJson("/api/equipment/eq-race/maintenances", """
137	                    {"requestId":"race-mnt","expectedVersion":3,"readingId":"r1","anchorRevisionNo":1}
138	                    """);
139	        });
140	        gate.countDown();
141	
142	        MvcResult revise = reviseFuture.get(15, TimeUnit.SECONDS);
143	        MvcResult maintenance = maintenanceFuture.get(15, TimeUnit.SECONDS);
144	        int reviseStatus = revise.getResponse().getStatus();
145	        int maintenanceStatus = maintenance.getResponse().getStatus();
146	
147	        // 恰有一个成功（201），另一个冲突（409）：版本校验使两者不能同时生效
148	        assertTrue(
149	                (reviseStatus == 201 && maintenanceStatus == 409)
150	                        || (reviseStatus == 409 && maintenanceStatus == 201),
151	                "修订与保养并发应恰有一个成功，实际：revise=" + reviseStatus
152	                        + ", maintenance=" + maintenanceStatus);
153	
154	        // 版本只前进一次
155	        mockMvc.perform(get("/api/equipment/eq-race/status"))
156	                .andExpect(jsonPath("$.version").value(4));
157	
158	        if (maintenanceStatus == 201) {
159	            // 保养胜出：锚点快照为修订号 1、工时 100，且之后不可再修订该读数
160	            mockMvc.perform(get("/api/equipment/eq-race/maintenances"))
161	                    .andExpect(jsonPath("$.length()").value(1))
