-- 可拆卸部件主表：合成编号唯一，寿命上限固定；累计寿命只随拆卸增加，设备保养不重置。
CREATE TABLE IF NOT EXISTS component (
    component_id VARCHAR(64) NOT NULL PRIMARY KEY,
    lifetime_minutes BIGINT NOT NULL,
    used_minutes BIGINT NOT NULL,
    version BIGINT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL
);
COMMENT ON TABLE component IS '可拆卸部件主表：每个部件一行，可在多台设备间轮换安装';
COMMENT ON COLUMN component.component_id IS '部件合成编号，全局唯一（客户端提供）';
COMMENT ON COLUMN component.lifetime_minutes IS '寿命上限（分钟），固定正整数，登记后不可修改';
COMMENT ON COLUMN component.used_minutes IS '已累计寿命（分钟），仅拆卸时按装拆区间差值累加，不因设备保养重置';
COMMENT ON COLUMN component.version IS '部件版本号，初始 1；安装/拆卸均校验 expectedVersion 并加一';
COMMENT ON COLUMN component.created_at IS '部件登记时刻（UTC）';

-- 部件装拆账：一次安装一行，拆卸时回填结束读数；区间左闭右开 [install, remove)，相邻接续合法。
CREATE TABLE IF NOT EXISTS component_installation (
    installation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    component_id VARCHAR(64) NOT NULL,
    equipment_id VARCHAR(64) NOT NULL,
    install_reading_id VARCHAR(64) NOT NULL,
    install_sampled_at TIMESTAMP WITH TIME ZONE NOT NULL,
    install_cumulative_minutes BIGINT NOT NULL,
    remove_reading_id VARCHAR(64),
    remove_sampled_at TIMESTAMP WITH TIME ZONE,
    remove_cumulative_minutes BIGINT,
    install_request_id VARCHAR(128) NOT NULL,
    remove_request_id VARCHAR(128),
    installed_at TIMESTAMP WITH TIME ZONE NOT NULL,
    removed_at TIMESTAMP WITH TIME ZONE
);
CREATE INDEX IF NOT EXISTS idx_installation_component ON component_installation (component_id, install_sampled_at);
CREATE INDEX IF NOT EXISTS idx_installation_equipment ON component_installation (equipment_id);
COMMENT ON TABLE component_installation IS '部件装拆账：安装记起始累计、拆卸记结束累计，差值计入部件累计寿命；被引用读数禁止修订';
COMMENT ON COLUMN component_installation.installation_id IS '装拆记录自增主键';
COMMENT ON COLUMN component_installation.component_id IS '部件合成编号';
COMMENT ON COLUMN component_installation.equipment_id IS '本次安装所在设备标识';
COMMENT ON COLUMN component_installation.install_reading_id IS '安装引用的设备累计读数标识（须已提交）';
COMMENT ON COLUMN component_installation.install_sampled_at IS '安装时刻，取安装读数的 UTC 采样时刻（快照）';
COMMENT ON COLUMN component_installation.install_cumulative_minutes IS '安装时设备累计工时快照（分钟）';
COMMENT ON COLUMN component_installation.remove_reading_id IS '拆卸引用的设备累计读数标识；NULL 表示当前仍安装在该设备上';
COMMENT ON COLUMN component_installation.remove_sampled_at IS '拆卸时刻，取拆卸读数的 UTC 采样时刻（快照）；未拆卸为 NULL';
COMMENT ON COLUMN component_installation.remove_cumulative_minutes IS '拆卸时设备累计工时快照（分钟），不得小于安装累计；未拆卸为 NULL';
COMMENT ON COLUMN component_installation.install_request_id IS '安装请求的 requestId';
COMMENT ON COLUMN component_installation.remove_request_id IS '拆卸请求的 requestId；未拆卸为 NULL';
COMMENT ON COLUMN component_installation.installed_at IS '安装登记时刻（UTC）';
COMMENT ON COLUMN component_installation.removed_at IS '拆卸登记时刻（UTC）；未拆卸为 NULL';

-- 幂等去重表：requestId 全局唯一；仅成功结果占键，失败回滚不占键。

